// ⭐ ENHANCED SpeechSynthesisEngine - Crystal Clear, Loud Voice
export class SpeechSynthesisEngine {
  constructor() {
    this.synthesis = window.speechSynthesis;
    this.voice = null;
    this.isSpeaking = false;
    this.currentUtterance = null;
  }

  async initialize() {
    if (!this.synthesis) return false;

    return new Promise((resolve) => {
      const loadVoices = () => {
        const voices = this.synthesis.getVoices();

        // ⭐ PRIORITY: Find the BEST quality voice (Google UK Female is clearest)
        this.voice = 
          // First choice: Google voices (clearest)
          voices.find(v => v.name.includes('Google UK English Female')) ||
          voices.find(v => v.name.includes('Google US English')) ||
          voices.find(v => v.name.includes('Google') && v.lang.startsWith('en')) ||

          // Second choice: Microsoft natural voices
          voices.find(v => v.name.includes('Microsoft') && v.name.includes('Natural') && v.lang.startsWith('en')) ||

          // Third choice: Any high-quality English voice
          voices.find(v => v.lang === 'en-US' && v.localService === false) ||
          voices.find(v => v.lang.startsWith('en-') && !v.localService) ||

          // Fallback
          voices.find(v => v.lang.startsWith('en')) ||
          voices[0];

        console.log('🔊 Selected voice:', this.voice?.name);
        console.log('📋 Available voices:', voices.map(v => v.name));
        resolve(true);
      };

      if (this.synthesis.getVoices().length > 0) {
        loadVoices();
      } else {
        this.synthesis.onvoiceschanged = loadVoices;
      }
    });
  }

  speak(text, options = {}) {
    return new Promise((resolve, reject) => {
      if (!this.synthesis) {
        return reject(new Error('Speech Synthesis not supported'));
      }

      // Cancel any ongoing speech
      this.synthesis.cancel();

      const utterance = new SpeechSynthesisUtterance(text);

      // ⭐ CRITICAL: Set voice FIRST before other properties
      utterance.voice = this.voice;

      // ⭐ OPTIMIZED SETTINGS for clarity and loudness
      utterance.rate = options.rate || 0.95;      // Slightly slower = clearer
      utterance.pitch = options.pitch || 1.1;     // Slightly higher = more engaging
      utterance.volume = options.volume || 1.0;   // MAX volume

      // ⭐ Break long text into chunks for better delivery
      utterance.lang = 'en-US';

      utterance.onstart = () => {
        this.isSpeaking = true;
        this.currentUtterance = utterance;
        console.log('🗣️ AI Speaking:', text.substring(0, 50) + '...');
        if (options.onStart) options.onStart();
      };

      utterance.onend = () => {
        this.isSpeaking = false;
        this.currentUtterance = null;
        console.log('✅ AI finished speaking');
        if (options.onEnd) options.onEnd();
        resolve();
      };

      utterance.onerror = (error) => {
        this.isSpeaking = false;
        this.currentUtterance = null;
        console.error('❌ Speech error:', error);
        if (options.onError) options.onError(error);

        // ⭐ FALLBACK: Retry once on error
        if (error.error === 'interrupted' || error.error === 'canceled') {
          console.log('🔄 Retrying speech...');
          setTimeout(() => {
            this.synthesis.speak(utterance);
          }, 100);
        } else {
          reject(error);
        }
      };

      // ⭐ CRITICAL: Small delay ensures voice is loaded
      setTimeout(() => {
        try {
          this.synthesis.speak(utterance);
        } catch (e) {
          console.error('Failed to speak:', e);
          reject(e);
        }
      }, 50);
    });
  }

  stop() {
    if (this.synthesis) {
      this.synthesis.cancel();
      this.isSpeaking = false;
      this.currentUtterance = null;
    }
  }

  pause() {
    if (this.synthesis && this.isSpeaking) {
      this.synthesis.pause();
    }
  }

  resume() {
    if (this.synthesis) {
      this.synthesis.resume();
    }
  }

  isSupported() {
    return !!window.speechSynthesis;
  }

  getSpeaking() {
    return this.isSpeaking;
  }

  // ⭐ NEW: Test voice quality
  async testVoice() {
    try {
      await this.speak('Hello! This is a voice quality test. Can you hear me clearly?', {
        rate: 0.95,
        pitch: 1.1,
        volume: 1.0
      });
      return true;
    } catch (error) {
      console.error('Voice test failed:', error);
      return false;
    }
  }
}
